INSERT INTO `config` (`config_id`, `api_key`, `base_url`, `stg_host`, `stg_username`, `stg_password`, `stg_db`, `warehouse_host`, `warehouse_username`, `warehouse_password`, `warehouse_db`, `dm_host`, `dm_username`, `dm_password`, `dm_db`,`create_time`, `update_time`, `query_M2`) VALUES
	(1, 'b1b15e88fa797225412429c1c50c122a1', 'https://api.openweathermap.org/data/2.5/forecast', 'localhost', 'root', '', 'staging-database', 'localhost', 'root', '', 'warehouse-database', 'localhost', 'root', '', 'datamart-database', '2025-11-13 10:46:49', '2025-11-13 19:24:05', 'INSERT INTO stg_weather_report (\r\n            location_sk,\r\n            actual_date_sk,\r\n            forecast_date_sk,\r\n            created_at_sk,\r\n            temp,\r\n            feels_like,\r\n            humidity,\r\n            wind_speed,\r\n            weather_type\r\n        )\r\n        SELECT \r\n            loc.location_id AS location_sk,\r\n            d_actual.date_sk AS actual_date_sk,\r\n            d_forecast.date_sk AS forecast_date_sk,\r\n            d_created.date_sk AS created_at_sk,\r\n            CAST(sr.temp AS DECIMAL(5,2)) AS temp,\r\n            CAST(sr.feels_like AS DECIMAL(5,2)) AS feels_like,\r\n            CAST(sr.humidity AS UNSIGNED) AS humidity,\r\n            CAST(sr.wind_speed AS DECIMAL(5,2)) AS wind_speed,\r\n            sr.weather_type\r\n        FROM stg_raw_data sr\r\n        LEFT JOIN stg_location loc \r\n            ON sr.location_id = loc.location_id \r\n            OR sr.city_name = loc.city_name\r\n        LEFT JOIN dim_date d_actual \r\n            ON d_actual.full_date = STR_TO_DATE(sr.dt, \'%Y-%m-%d\')\r\n        LEFT JOIN dim_date d_forecast \r\n            ON d_forecast.full_date = STR_TO_DATE(sr.forecast_dt, \'%Y-%m-%d\')\r\n        LEFT JOIN dim_date d_created \r\n            ON d_created.full_date = STR_TO_DATE(sr.created_at, \'%Y-%m-%d\');');
